package execution
import("context";"encoding/json";"net/http";"net/http/httptest";"testing")
func TestComputecloudProviderSubmitAndGet(t *testing.T){var key string;s:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){if r.URL.Path=="/v1/jobs"{key=r.Header.Get("Idempotency-Key");_=json.NewEncoder(w).Encode(map[string]string{"job_id":"job-1"});return};if r.URL.Path=="/v1/jobs/job-1"{_=json.NewEncoder(w).Encode(map[string]string{"state":"SUCCEEDED"});return};http.NotFound(w,r)}));defer s.Close();p:=&ComputecloudProvider{BaseURL:s.URL,Client:s.Client(),BuildJob:func(r ExecutionRequest)(any,error){return map[string]any{"input":r.Goal},nil}};ref,e:=p.Submit(context.Background(),ExecutionRequest{ID:"exec-1",Goal:"fix bug"});if e!=nil{t.Fatal(e)};if key!="exec-1"||ref.ID!="job-1"{t.Fatalf("bad mapping")};st,e:=p.Get(context.Background(),ref);if e!=nil{t.Fatal(e)};if st.Phase!=ExecutionCompleted{t.Fatalf("phase=%s",st.Phase)}}
